package tracelet.policy

import rego.v1

default matched := false
default reason := ""

tool_input := ti if {
	ti := object.get(input.event, ["raw_json", "tool_input"], {})
	is_object(ti)
}

default tool_input := {}

candidate_texts contains t if {
	some k in ["content", "new_string", "new_str", "text", "code", "contents"]
	t := object.get(tool_input, k, "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	some e in object.get(tool_input, "edits", [])
	is_object(e)
	t := object.get(e, "new_string", "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	t := object.get(input.event, "command_text", "")
	is_string(t)
	t != ""
}

scan_text := concat("\n", [t | some t in candidate_texts])

file_path := object.get(input.event, "file_path", "")

# Admin-equivalent grants: Action "*" / "*:*" / privilege-escalation services
# (iam, sts, organizations) with a wildcard, or the AdministratorAccess /
# PowerUserAccess / IAMFullAccess managed policies — in JSON, HCL and CFN YAML.
admin_patterns := [
	`(?i)"Action"\s*:\s*"(?:\*|\*:\*|(?:iam|sts|organizations):\*)"`,
	`(?i)"Action"\s*:\s*\[[^\]]*"(?:\*|\*:\*|(?:iam|sts|organizations):\*)"`,
	`(?i)"NotAction"\s*:`,
	`(?i)\bactions?\s*=\s*\[?\s*"(?:\*|\*:\*|(?:iam|sts|organizations):\*)"`,
	`(?im)^\s*-?\s*Action\s*:\s*['"]?(?:\*|\*:\*|(?:iam|sts|organizations):\*)['"]?\s*$`,
	`(?im)^\s*Action\s*:\s*$\n\s*-\s*['"]?(?:\*|\*:\*|(?:iam|sts|organizations):\*)['"]?\s*$`,
	`arn:aws[a-z-]*:iam::aws:policy/(?:AdministratorAccess|PowerUserAccess|IAMFullAccess)\b`,
	`(?i)"Principal"\s*:\s*(?:"\*"|\{\s*"AWS"\s*:\s*"\*")`,
	`(?i)\bprincipals?\s*\{[^}]*identifiers\s*=\s*\[\s*"\*"`,
]

matched if {
	scan_text != ""
	some p in admin_patterns
	regex.match(p, scan_text)
}

reason := sprintf("Admin-equivalent IAM grant (wildcard action, wildcard principal, or Administrator/PowerUser/IAMFullAccess) written to %s — scope the policy to the specific actions and ARN prefixes the workload needs", [display_path]) if {
	matched
}

display_path := file_path if { file_path != "" }
display_path := "the command" if { file_path == "" }

package tracelet.policy

import rego.v1

default matched := false
default reason := ""

tool_input := ti if {
	ti := object.get(input.event, ["raw_json", "tool_input"], {})
	is_object(ti)
}

default tool_input := {}

candidate_texts contains t if {
	some k in ["content", "new_string", "new_str", "text", "code", "contents"]
	t := object.get(tool_input, k, "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	some e in object.get(tool_input, "edits", [])
	is_object(e)
	t := object.get(e, "new_string", "")
	is_string(t)
	t != ""
}

candidate_texts contains t if {
	t := object.get(input.event, "command_text", "")
	is_string(t)
	t != ""
}

scan_text := concat("\n", [t | some t in candidate_texts])

file_path := object.get(input.event, "file_path", "")

# Service-wide action wildcards (s3:*, ec2:*, ...) or a bare Resource "*" on
# a statement — broader than the task needs. Read-only wildcards
# (Describe*/Get*/List*) are deliberately not matched.
wide_patterns := [
	`(?i)"Action"\s*:\s*"[a-z0-9-]+:\*"`,
	`(?i)"Action"\s*:\s*\[[^\]]*"[a-z0-9-]+:\*"`,
	`(?i)\bactions?\s*=\s*\[?\s*"[a-z0-9-]+:\*"`,
	`(?im)^\s*-?\s*Action\s*:\s*['"]?[a-z0-9-]+:\*['"]?\s*$`,
	`(?i)"Resource"\s*:\s*"\*"`,
	`(?i)"Resource"\s*:\s*\[[^\]]*"\*"`,
	`(?i)\bresources?\s*=\s*\[?\s*"\*"`,
	`(?im)^\s*-?\s*Resource\s*:\s*['"]?\*['"]?\s*$`,
	`arn:aws[a-z-]*:iam::aws:policy/[A-Za-z0-9]+FullAccess\b`,
]

# The admin-equivalent shapes are handled by the request_access rule; skip
# them here so one write does not raise two prompts.
admin_shape if {
	regex.match(`(?i)"Action"\s*:\s*"(?:\*|\*:\*|(?:iam|sts|organizations):\*)"`, scan_text)
}

matched if {
	scan_text != ""
	not admin_shape
	some p in wide_patterns
	regex.match(p, scan_text)
}

reason := sprintf("Service-wide action wildcard, bare Resource \"*\", or a *FullAccess managed policy written to %s — prefer explicit actions and an ARN prefix with a trailing wildcard (arn:aws:s3:::team-bucket-*) so renamed resources keep matching without granting everything", [display_path]) if {
	matched
}

display_path := file_path if { file_path != "" }
display_path := "the command" if { file_path == "" }
